solution:
// file: main.xi
mod math {
    pub fn add(a: Int, b: Int) -> Int {
        return a + b
    }

    pub fn multiply(a: Int, b: Int) -> Int {
        return a * b
    }
}

fn main() {
    io.println("add: {math::add(5, 7)}")
    io.println("multiply: {math::multiply(6, 8)}")
}
